c=new C();
for(let i=0;i<50;i++){c.step();}
const x0=c.V[0];
c.keys[6]=true;
for(let i=0;i<2000;i++){if(c.delay===0&&c.V[2]===0){c.step();if(c.delay>0){c.keys[6]=false;break;}}c.step();c.tickTimers();}
