{"path":"c8test.js","content":"const fs = require('fs');
const html = fs.readFileSync(__dirname + '/chip8_zai-glm-5.3_01.html', 'utf8');
const src = html.match(/<script>([\s\S]*)<\/script>/)[1];
const noop = () => {};
function fakeEl() {
  return { getContext: () => ({ fillStyle: '', fillRect: noop }), appendChild: noop,
    addEventListener: noop, textContent: '', value: 15, innerHTML: '',
    classList: { toggle: noop, add: noop, remove: noop }, style: {}, files: [],
    onclick: null, oninput: null, onchange: null };
}
global.document = { getElementById: fakeEl, createElement: fakeEl, addEventListener: noop };
global.window = global; global.requestAnimationFrame = noop;
global.AudioContext = function () {
  return { createOscillator: () => ({ connect: noop, start: noop, stop: noop, frequency: { value: 0 } }),
    createGain: () => ({ connect: noop, gain: { value: 0 } }), destination: {} };
};
global.FileReader = function () {};
eval(src + "\n;global.C=Chip8;global.DEMO=DEMO_ROM;global.DIS=disassemble;");

let fails = 0;
const ok = (n, c) => { if (!c) { fails++; console.log('FAIL', n); } };
function run(prog) { // prog = array of 16-bit ops; returns cpu after executing all
  const c = new C();
  const bytes = [];
  prog.forEach(op => bytes.push((op >> 8) & 0xFF, op & 0xFF));
  c.loadROM(new Uint8Array(bytes));
  for (let i = 0; i < 2000 && !c.halted; i++) c.step();
  return c;
}

ok('font', C && new C().memory[0x50] === 0xF0 && new C().memory[0x50 + 79] === 0x80);
let c = run([0x6005]); ok('LD Vx,nn', c.V[0] === 5);
c = run([0x6103, 0x8014]); ok('ADD carry', c.V[0] === 8 && c.V[0xF] === 0);
c = run([0x60F0, 0x6115, 0x8014]); ok('ADD carry set', c.V[0] === 0x05 && c.V[0xF] === 1);
c = run([0x6005, 0x6103, 0x8015]); ok('SUB no borrow', c.V[0] === 2 && c.V[0xF] === 1);
c = run([0x6003, 0x6105, 0x8015]); ok('SUB borrow', c.V[0] === 0xFE && c.V[0xF] === 0);
c = run([0x6003, 0x6105, 0x8017]); ok('SUBN', c.V[0] === 2 && c.V[0xF] === 1);
c = run([0x6005, 0x6103, 0x8017]); ok('SUBN neg', c.V[0] === 0xFE && c.V[0xF] === 0);
c = run([0x6081, 0x8016]); ok('SHR lsb', c.V[0] === 0x40 && c.V[0xF] === 1);
c = run([0x6081, 0x801E]); ok('SHL msb', c.V[0] === 0x02 && c.V[0xF] === 1);
c = run([0x60F0, 0x6100F & 0xFFFF || 0x610F, 0x8011]); ok('OR', c.V[0] === 0xFF);
c = run([0x60F0, 0x610F, 0x8012]); ok('AND', c.V[0] === 0x00);
c = run([0x60F0, 0x610F, 0x8013]); ok('XOR', c.V[0] === 0xFF);
c = run([0x60F0, 0x6112, 0x8010]); ok('LD Vx,Vy', c.V[0] === 0x12);
c = run([0x6005, 0x7003]); ok('ADD Vx,nn', c.V[0] === 8);
c = run([0x6005, 0x70FF]); ok('ADD Vx,nn wrap', c.V[0] === 4);
// skips
c = run([0x6005, 0x3005, 0x1111]); ok('SE skip', c.PC === 0x206);
c = run([0x6005, 0x3006, 0x1111]); ok('SE noskip', c.PC === 0x204);
c = run([0x6005, 0x4006, 0x1111]); ok('SNE skip', c.PC === 0x206);
c = run([0x6005, 0x6105, 0x5010, 0x1111]); ok('SE Vx,Vy', c.PC === 0x208);
c = run([0x6005, 0x6106, 0x9010, 0x1111]); ok('SNE Vx,Vy', c.PC === 0x208);
// jump/call
c = run([0x1206]); ok('JP', c.PC === 0x206);
c = new C(); c.loadROM(new Uint8Array([0x22,0x08, 0,0, 0,0, 0x00,0xEE]));
c.step(); ok('CALL', c.PC === 0x208 && c.stack.length === 1 && c.stack[0] === 0x202);
c.step(); ok('RET', c.PC === 0x202 && c.stack.length === 0);
c = run([0x6005, 0xB201]); ok('JP V0', c.PC === 0x206);
// misc
c = run([0xA123]); ok('LD I', c.I === 0x123);
c = run([0x6005, 0xF115]); ok('LD DT', c.delay === 5);
c = run([0x6005, 0xF118]); ok('LD ST', c.sound === 5);
c = run([0xA200, 0x6005, 0xF11E]); ok('ADD I', c.I === 0x205);
c = run([0x6007, 0xF029]); ok('FONT', c.I === 0x50 + 35);
c = run([0xA300, 0x60B4, 0xF033]);
ok('BCD', c.memory[0x300] === 1 && c.memory[0x301] === 8 && c.memory[0x302] === 0);
c = run([0xA300, 0x60AB, 0x61CD, 0x6203, 0xF255]);
ok('STORE', c.memory[0x300] === 0xAB && c.memory[0x301] === 0xCD && c.memory[0x302] === 0x03);
c = new C(); c.loadROM(new Uint8Array([0xA3,0x00, 0xF2,0x65]));
c.memory[0x300] = 1; c.memory[0x301] = 2; c.memory[0x302] = 3; c.step();
ok('LOAD', c.V[0] === 1 && c.V[1] === 2 && c.V[2] === 3);
// timers
c = new C(); c.delay = 5; c.sound = 3; c.tickTimers();
ok('timers dec', c.delay === 4 && c.sound === 2);
// draw + collision
c = new C(); c.loadROM(new Uint8Array([0xA3,0x00, 0x60,0x00, 0x61,0x00, 0xD0,0x11]));
c.memory[0x300] = 0xFF; c.step();
ok('DRAW set', c.display[0] === 1 && c.display[7] === 1 && c.display[64] === 1 && c.V[0xF] === 0);
c = new C(); c.loadROM(new Uint8Array([0xA3,0x00, 0x60,0x00, 0x61,0x00, 0xD0,0x11, 0xD0,0x11]));
c.memory[0x300] = 0xFF; c.step(); c.step();
ok('DRAW collide/XOR', c.display[0] === 0 && c.V[0xF] === 1);
// keys
c = new C(); c.loadROM(new Uint8Array([0x60,0x05, 0xE0,0x9E, 0x12,0x02]));
c.keyPress(5); c.step(); c.step(); ok('SKP', c.PC === 0x206);
c = new C(); c.loadROM(new Uint8Array([0x60,0x05, 0xE0,0xA1, 0x12,0x02]));
c.keyPress(5); c.step(); c.step(); ok('SKNP blocked', c.PC === 0x202);
c.keyRelease(5); c.step(); ok('SKNP after release', c.PC === 0x204);
// FX0A
c = new C(); c.loadROM(new Uint8Array([0xF0,0x0A, 0x60,0x01]));
c.step(); ok('FX0A waits', c.waitingKey === 0 && c.PC === 0x202);
c.keyPress(7); ok('FX0A captured', c.V[0] === 7 && c.waitingKey === -1 && c.PC === 0x202);
c.step(); ok('FX0A resumes', c.V[0] === 7 && c.PC === 0x204);
// CLS
c = new C(); c.loadROM(new Uint8Array([0xA3,0x00, 0x60,0x00, 0x61,0x00, 0xD0,0x11, 0x00,0xE0]));
c.memory[0x300] = 0xFF; c.step(); c.step(); ok('CLS', c.display.every(p => p === 0));
// RND
c = run([0x60FF, 0xC0FF & 0xC0FF, 0xC0FF]); // D012 style not needed; just RND C0 FF pattern
// (RND covered loosely)
c = new C(); c.loadROM(new Uint8Array([0xC0,0x00]));
c.step(); ok('RND mask', c.V[0] === 0);
// demo ROM sanity: run many steps with key 6 held -> sprite moves right, display has pixels
c = new C(); c.loadROM(new Uint8Array(DEMO));
c.delay = 0;
for (let i = 0; i < 5000; i++) { if (c.delay === 0) c.delay = 1; c.keyPress(6); c.step(); c.tickTimers(); }
ok('demo draws', c.display.some(p => p === 1));
ok('demo moved right', c.V[0] > 28);
// disassembler spot checks
ok('DIS CLS', DIS(0x00E0) === 'CLS');
ok('DIS DRW', DIS(0xD015).startsWith('DRW'));
ok('DIS JP', DIS(0x1200).startsWith('JP'));

console.log(fails === 0 ? 'ALL TESTS PASSED' : fails + ' FAILURES');
process.exit(fails ? 1 : 0);
"}

